n=19
centers=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
orig3={(2,6),(3,5),(3,7),(4,6),(3,13),(4,12),(4,14),(5,13), (9,8),(10,7),(10,9),(11,8), (11,14),(12,13),(12,15),(13,14), (13,3),(14,2),(14,4),(15,3)}
own={}
for r,c,v in centers:
    own[(r,c)]={(r-1,c),(r+1,c),(r,c-1),(r,c+1)}
# draw rays from each center; obstacle marker stops unless own arm
# horizontal first, then vertical. Keep all 3s.
g=[[0]*n for _ in range(n)]
for r,c,v in centers:g[r][c]=v
for axis in ['h','v']:
  for r,c,v in centers:
    dirs=[(0,-1),(0,1)] if axis=='h' else [(-1,0),(1,0)]
    for dr,dc in dirs:
      rr,cc=r+dr,c+dc
      while 0<=rr<n and 0<=cc<n:
        if (rr,cc) in orig3:
          g[rr][cc]=3
          if (rr,cc) not in own[(r,c)]: break
        else:
          g[rr][cc]=v
        rr+=dr;cc+=dc
for r,c in orig3:g[r][c]=3
for r,c,v in centers:g[r][c]=v
print('\n'.join(' '.join(map(str,row)) for row in g))

